style.css:
/* Joker After Dark — Global */
 /* i really want this to be global */

/* Couleurs modifiables ici */
:root {
  --my-bg: #080808;
  --my-surface: #141414;
  --my-text: #dedede;
  --my-muted: #858585;
  --my-red: #b51224;
  --my-red-hover: #ed2339;
}

/* Fond et texte */
html {
  color-scheme: dark !important;
  background: var(--my-bg) !important;
}

body {
  background-color: var(--my-bg) !important;
  color: var(--my-text) !important;
}

/* Titres */
h1, h2, h3, h4 {
  color: #eeeeee !important;
}

/* Liens rouges */
a {
  color: var(--my-red) !important;
  transition: color .2s ease !important;
}

a:hover {
  color: var(--my-red-hover) !important;
}

/* Boutons */
button {
  border-radius: 8px !important;
  transition: .2s ease !important;
}

button:hover {
  border-color: var(--my-red) !important;
}

/* Champs de texte */
input, textarea, select {
  background: var(--my-surface) !important;
  color: var(--my-text) !important;
  border: 1px solid #292929 !important;
  border-radius: 7px !important;
}

/* Séparateurs */
hr {
  border-color: #292929 !important;
}
